package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.io.*;
public final class PcWorldMeshReferenceExport {
 static void floats(DataOutputStream out,FloatBuffer f)throws Exception{out.writeInt(f.remaining());while(f.hasRemaining())out.writeInt(Integer.reverseBytes(Float.floatToRawIntBits(f.get())));}
 public static void main(String[] args)throws Exception{Path output=Paths.get(args[1]);Files.createDirectories(output);int worlds=0,surfaces=0,vertices=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(Paths.get(args[0]),"*.nsp")){for(Path file:files){NativeScenePacket packet=new NativeScenePacket(1,Files.readAllBytes(file));NativeWorldScene world=new NativeWorldScene(packet);try(DataOutputStream out=new DataOutputStream(Files.newOutputStream(output.resolve(file.getFileName().toString().replace(".nsp",".mesh"))))){out.writeInt(world.surfaceCount());for(int i=0;i<world.surfaceCount();i++){NativeWorldMesh mesh=new NativeWorldMesh(packet,world,i);out.writeInt(mesh.affine?1:0);out.writeInt(mesh.surface.sourceCamera()!=null?1:0);DoubleBuffer camera=mesh.cameraVertices();out.writeInt(camera.remaining());while(camera.hasRemaining())out.writeLong(Long.reverseBytes(Double.doubleToRawLongBits(camera.get())));floats(out,mesh.vertices());out.writeInt(mesh.triangleVertices/3);for(int tri=0;tri<mesh.triangleVertices;tri+=3){NativeTexturePlane plane=new NativeTexturePlane(mesh.vertices(),tri);FloatBuffer values=FloatBuffer.allocate(11);values.put(plane.x).put(plane.y).put(plane.base).put(plane.dx).put(plane.dy).flip();while(values.hasRemaining())out.writeInt(Integer.reverseBytes(Float.floatToRawIntBits(values.get())));}surfaces++;vertices+=mesh.triangleVertices;}}worlds++;}}System.out.println("PASS_PC_WORLD_MESH_JAVA_EXPORT worlds="+worlds+" surfaces="+surfaces+" triangle_vertices="+vertices);}
}
